const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
const api=vm.createContext({});vm.runInContext(fs.readFileSync(path.resolve(__dirname,'../../internal/web/static/js/survey-workstation.js'),'utf8'),api);
const snapshot=(node,finished,detail,status='observed')=>({snapshot:{profile:'alt-workstation',node,site:'Branch',finished,checks:[{source:'DNS config',status,detail}]}});
const before=snapshot('WS.EXAMPLE.TEST.','2026-11-10T10:00:00Z','old');
const after=snapshot('ws.example.test','2026-11-10T11:00:00Z','new');
assert.equal(api.surveyCompareStations(before,after).rows[0][3],'Изменение наблюдаемых данных');
const missing=snapshot('ws.example.test','2026-11-10T12:00:00Z','timeout','unknown');
assert.match(api.surveyCompareStations(before,missing).rows[0][3],/Нет достоверной пары/);
assert.match(api.surveyCompareStations(after,before).error,/старше/);
assert.match(api.surveyCompareStations(before,snapshot('another.example.test',after.snapshot.finished,'new')).error,/одинаковым FQDN/);
const old=api.surveyStationModel(before,Date.parse('2026-11-12T00:00:00Z'));
assert.match(old.warnings.join(' '),/Старый снимок.*резолверы.*старше суток/);
const f={path:'/etc/sssd/sssd.conf',status:'observed',mode:'0600',owner:'root:root',settings:[{section:'domain/example.test',key:'ad_server',value:'dc1.example.test'}]};
before.snapshot.workstation={format:1,configs:[f],dns:[{resolver:'192.0.2.53',name:'app.example.test.',type:'A',transport:'udp',status:'observed',rcode:'NOERROR',answers:['app.example.test. 300 IN A 192.0.2.1']}]};
after.snapshot.workstation=JSON.parse(JSON.stringify(before.snapshot.workstation));
after.snapshot.workstation.dns[0].answers=['app.example.test. 200 IN A 192.0.2.1'];
before.snapshot.checks=[];after.snapshot.checks=[];
assert.equal(api.surveyCompareStations(before,after).rows.length,0,'TTL ageing is not a changed target');
after.snapshot.workstation.configs[0].settings=[];
assert.match(api.surveyCompareStations(before,after).rows.find(r=>r[0].startsWith('Параметр'))[3],/удаление не установлено/);
console.log('Workstation survey model checks passed');
